pragma solidity >=0.8.0;

contract GasMonotonicProbe {
    uint256 public entrySeen;
    uint256 public exitSeen;
    uint256 public consumed;

    event GasSeen(uint256 entry, uint256 exit, uint256 used);

    function getGas() public view returns (uint256) {
        return gasleft();
    }

    function snapshotGas() public {
        uint256 e = gasleft();
        uint256 s = 0;
        for (uint256 i = 0; i < 100; i++) {
            s += i;
        }
        uint256 x = gasleft();
        require(x < e, "gas not monotonic");
        require(s == 4950, "bad sum");
        entrySeen = e;
        exitSeen = x;
        consumed = e - x;
        emit GasSeen(e, x, consumed);
    }
}
